using System;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
namespace JonsboStudio {
 sealed partial class AppForm {
  readonly DeviceStartup startupGuard=new DeviceStartup();
  Task StartEngine(PlaybackEngine next,string port){return startupGuard.Start(port,next.Start,next.CancelStartup,next.Dispose);}
  bool officialAppRunning;readonly Dictionary<string,string> reconnectErrors=new Dictionary<string,string>();
  static string Model(string port){return port==MsDisplayTransport.PortId?"DS339":"DS916";}
  object[] ConnectionStates(){return new[]{"DS916","DS339"}.Select(model=>{
   var device=devices.FirstOrDefault(d=>Model(d.port)==model);var session=engines.FirstOrDefault(e=>e.Value.Hardware&&Model(e.Key)==model).Value;
   var profile=deviceSettings.FirstOrDefault(s=>Model(s.Key)==model).Value;string last;reconnectErrors.TryGetValue(model,out last);
   string state=session!=null?session.ConnectionState:device!=null?(device.ready?"detected":"blocked"):"disconnected";
   string message=session!=null?session.ConnectionMessage:last??(device!=null?(device.ready?"Detected · "+device.port:device.problemCode==14?"Windows requires a restart for this USB interface.":"USB interface is present but not ready. Reconnect its cable, then refresh."):"Not detected. Check USB, then refresh devices.");
   return (object)new{model=model,port=session!=null?session.ConnectionPort:device==null?"":device.port,state=state,message=message,connected=session!=null&&session.Connected,available=device!=null,hasTheme=profile!=null&&File.Exists(profile.ThemePath)};
  }).ToArray();}
  void SyncConnectionPorts(){bool changed=false;foreach(var pair in engines.ToArray()){
   string port=pair.Value.ConnectionPort;if(!pair.Value.Hardware||!pair.Value.Connected||string.IsNullOrEmpty(port)||port==pair.Key||engines.ContainsKey(port))continue;
   StudioSettings config;if(!deviceSettings.TryGetValue(pair.Key,out config))continue;engines.Remove(pair.Key);engines[port]=pair.Value;deviceSettings.Remove(pair.Key);config.Port=port;deviceSettings[port]=config;
   var device=devices.FirstOrDefault(d=>d.port==pair.Key);if(device!=null)device.port=port;changed=true;
  }if(changed)SaveSettings();}
  async Task RefreshConnections(){if(busy)return;busy=true;status="Refreshing display connections…";SendState();try{
   var found=await Task.Run(()=>JonsboTransport.Discover());officialAppRunning=Process.GetProcessesByName("JONSBO-AIO").Length>0;devices=found;SyncConnectionPorts();
   foreach(var device in devices)if(!deviceSettings.ContainsKey(device.port)){var existing=deviceSettings.FirstOrDefault(s=>Model(s.Key)==Model(device.port)).Value;var config=existing==null?StudioSettings.ForDevice(device.port):Newtonsoft.Json.JsonConvert.DeserializeObject<StudioSettings>(Newtonsoft.Json.JsonConvert.SerializeObject(existing));config.Port=device.port;config.ThemePath=CompatibleTheme(config,config.ThemePath);deviceSettings[device.port]=config;}
   status=officialAppRunning?"Both apps share the displays. Exit the official JONSBO app from its tray before reconnecting Studio.":devices.Count+" supported display(s) detected. Running displays were kept active.";
  }finally{busy=false;SendState();}}
  async Task ReconnectDisplay(string model){if(model!="DS916"&&model!="DS339")throw new ArgumentException("Choose DS916 or DS339.");if(busy)return;await RefreshConnections();busy=true;status="Reconnecting JONSBO "+model+"…";SendState();try{
   var running=engines.FirstOrDefault(e=>e.Value.Hardware&&Model(e.Key)==model);
   if(running.Value!=null&&running.Value.Error.Length==0){running.Value.RequestReconnect();reconnectErrors.Remove(model);status="Reconnect requested for JONSBO "+model+". Its saved theme, settings and prepared cache are retained.";return;}
   var device=devices.FirstOrDefault(d=>Model(d.port)==model);if(device==null)throw new IOException("JONSBO "+model+" is not detected. Check its USB cable and power, then refresh devices.");
   StudioSettings config;if(!deviceSettings.TryGetValue(device.port,out config))throw new InvalidOperationException("No display profile is available. Refresh devices first.");
   if(!File.Exists(config.ThemePath))throw new InvalidOperationException("Select a local or online theme for JONSBO "+model+" first, then reconnect.");
   if(!device.ready)throw new IOException(device.problemCode==14?"Windows requires a restart for the "+model+" USB interface.":"The "+model+" USB interface is not ready. Reconnect its cable and refresh devices.");var document=ThemeDocument.Load(config.ThemePath);if(running.Value!=null){engines.Remove(running.Key);await Task.Run(()=>running.Value.Dispose());}
   var next=new PlaybackEngine(document,config,true);try{await StartEngine(next,config.Port);}catch{if(!startupGuard.IsPending(config.Port))next.Dispose();throw;}engines[device.port]=next;reconnectErrors.Remove(model);lastPlaybackError="";SaveSettings();status="JONSBO "+model+" reconnected with its saved theme and output settings.";
  }catch(Exception error){reconnectErrors[model]=error.Message;status=error.Message;FirstRunSetup.Log(error,"Manual reconnect "+model);throw;}finally{busy=false;SendState();}}
  public async Task ReconnectSmoke(string first,string second){Console.WriteLine("Reconnect smoke: waiting for UI");for(int i=0;i<100&&!ready;i++)await Task.Delay(100);if(!ready)throw new Exception("UI failed to initialize.");Console.WriteLine("Reconnect smoke: opening DS916");SelectDevice("COM12");current=ThemeDocument.Load(first);settings.ThemePath=first;await Play(true);if(engine==null)throw new Exception(status);Console.WriteLine("Reconnect smoke: opening DS339");SelectDevice(MsDisplayTransport.PortId);current=ThemeDocument.Load(second);settings.ThemePath=second;await Play(true);if(engine==null)throw new Exception(status);
   Console.WriteLine("Reconnect smoke: both engines started");var a=engines["COM12"];var b=engines[MsDisplayTransport.PortId];await web.CoreWebView2.ExecuteScriptAsync("navigate('settings')");await Task.Delay(1000);
   foreach(string model in new[]{"DS916","DS339","DS339"}){var target=model=="DS916"?a:b;var other=model=="DS916"?b:a;Console.WriteLine("Reconnect smoke: clicking "+model);int generation=target.ConnectionGeneration;long sentOther=other.Sent;await web.CoreWebView2.ExecuteScriptAsync("document.getElementById('reconnect-"+model.ToLowerInvariant()+"').click()");for(int i=0;i<400&&(busy||target.ConnectionGeneration<=generation||!target.Connected);i++)await Task.Delay(50);if(!target.Connected||target.ConnectionGeneration<=generation||target.Error.Length>0||other.Error.Length>0||other.Sent<=sentOther)throw new Exception("Reconnect failed or interrupted the other display: "+model+" "+target.ConnectionMessage);Console.WriteLine("PASS: Settings reconnect "+model+"; native generation "+target.ConnectionGeneration+"; other display sent "+(other.Sent-sentOther)+" frames.");}
   await web.CoreWebView2.ExecuteScriptAsync("document.getElementById('scan').click()");for(int i=0;i<200&&busy;i++)await Task.Delay(50);if(devices.Count<2||!a.Connected||!b.Connected)throw new Exception("Refresh lost a running device.");long ca=a.Sent,cb=b.Sent;var process=Process.GetCurrentProcess();var cpu=process.TotalProcessorTime;var watch=Stopwatch.StartNew();await Task.Delay(10000);process.Refresh();double seconds=watch.Elapsed.TotalSeconds;Console.WriteLine("After reconnect: DS916="+((a.Sent-ca)/seconds).ToString("F1")+" FPS; DS339="+((b.Sent-cb)/seconds).ToString("F1")+" FPS; CPU="+(100*(process.TotalProcessorTime-cpu).TotalSeconds/seconds/Environment.ProcessorCount).ToString("F2")+"%");if((a.Sent-ca)/seconds<55||(b.Sent-cb)/seconds<55)throw new Exception("Playback did not recover its frame rate.");
  }

  public async Task Ds339ReconnectSmoke(string path){for(int i=0;i<100&&!ready;i++)await Task.Delay(100);if(!ready)throw new Exception("UI failed to initialize.");SelectDevice(MsDisplayTransport.PortId);current=ThemeDocument.Load(path);settings.ThemePath=path;await Play(true);if(engine==null)throw new Exception(status);var display=engine;await web.CoreWebView2.ExecuteScriptAsync("navigate('settings')");await Task.Delay(500);for(int attempt=0;attempt<3;attempt++){int generation=display.ConnectionGeneration;await web.CoreWebView2.ExecuteScriptAsync("document.getElementById('reconnect-ds339').click()");for(int i=0;i<400&&(busy||display.ConnectionGeneration<=generation||!display.Connected);i++)await Task.Delay(50);if(!display.Connected||display.ConnectionGeneration<=generation||display.Error.Length>0)throw new Exception("DS339 reconnect failed: "+display.ConnectionMessage);Console.WriteLine("PASS: DS339 Settings reconnect, SDK generation "+display.ConnectionGeneration);await Task.Delay(1000);}long sent=display.Sent;await RefreshConnections();await Task.Delay(5000);if(!display.Connected||display.Sent<=sent)throw new Exception("DS339 stopped after refresh.");Console.WriteLine("PASS: DS339 remained playing after three native SDK reconnects and device refresh.");int beforeReset=display.ConnectionGeneration;string instance=devices.First(d=>d.port==MsDisplayTransport.PortId).hardwareId;if(!instance.StartsWith(@"USB\VID_345F&PID_9132&MI_03\",StringComparison.OrdinalIgnoreCase)||instance.Contains("\""))throw new Exception("Unexpected DS339 interface identity.");await Task.Run(()=>{var info=new ProcessStartInfo(System.IO.Path.Combine(Environment.SystemDirectory,"pnputil.exe"),"/restart-device \""+instance+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var process=Process.Start(info)){string output=process.StandardOutput.ReadToEnd();if(!process.WaitForExit(20000))throw new Exception("USB restart did not finish.");Console.WriteLine(output);if(process.ExitCode!=0)throw new Exception("USB restart requires Windows attention: "+process.ExitCode);}});for(int i=0;i<600&&(!display.Connected||display.ConnectionGeneration<=beforeReset);i++)await Task.Delay(50);if(!display.Connected||display.ConnectionGeneration<=beforeReset)throw new Exception("Automatic reconnect after USB restart failed: "+display.ConnectionMessage);long recovered=display.Sent;await Task.Delay(1500);if(display.Sent<=recovered)throw new Exception("No frames after automatic reconnect.");Console.WriteLine("PASS: DS339 recovered automatically after its exact USB interface was restarted; generation "+display.ConnectionGeneration);}

 }
}
